/* Integração nas telas existentes, usando os cadastros e frequência oficiais locais. */
(()=>{'use strict';const J=MartinsJornada,$=id=>document.getElementById(id);
const style=document.createElement('style');style.textContent='#mj-dialog{box-sizing:border-box;width:min(960px,calc(100vw - 16px));max-width:calc(100vw - 16px);max-height:90vh;padding:22px;border:1px solid #b6954c;border-radius:14px}#mj-close-top{position:sticky;top:0;float:right;z-index:2}#mj-dialog h2{font-size:1.25rem;font-weight:700;margin-bottom:12px}#mj-dialog h3{font-weight:700;margin-top:16px}#mj-dialog::backdrop{background:#0008}#mj-dialog label{display:block;margin:10px 0}#mj-dialog input,#mj-dialog select{padding:9px;border:1px solid #aaa;border-radius:5px;max-width:100%}#mj-dialog button,.mj-open{padding:10px;background:#765b28;color:white;border-radius:6px;margin:5px}#mj-dialog td,#mj-dialog th{padding:8px;border-bottom:1px solid #ddd;text-align:left}#mj-dialog table{width:100%}#mj-msg{white-space:pre-wrap}';document.head.append(style);
const dialog=document.createElement('dialog');dialog.id='mj-dialog';dialog.innerHTML=`<button id="mj-close-top" type="button" aria-label="Fechar planejamento">Fechar</button><h2>Planejamento integrado à Frequência</h2><p>Use os cadastros atuais. Planejamento é previsão: selecione e confira os presentes antes de confirmar. Registros existentes permanecem preservados. O rateio entre obras preserva as horas de cada obra na jornada e no RDO.</p><label>Dia <input id="mj-day" type="date"></label><label>Funcionário <select id="mj-person"></select></label><label>Obra <select id="mj-work"></select></label><label>Horas planejadas <input id="mj-hours" type="number" min="0.25" max="8" step="0.25" value="8"></label><button id="mj-plan" type="button">Salvar planejamento</button><label>Copiar planejamento deste dia para (datas separadas por vírgulas)<input id="mj-dates" placeholder="2026-11-06,2026-11-09"></label><button id="mj-copy" type="button">Copiar sem substituir destinos</button><div style="overflow:auto"><table><thead><tr><th>Confirmar presença</th><th>Funcionário</th><th>Obra / horas</th><th>Frequência atual</th></tr></thead><tbody id="mj-rows"></tbody></table></div><button id="mj-refresh" type="button">Atualizar conferência</button><button id="mj-confirm" type="button">Confirmar selecionados na Frequência</button><button id="mj-close" type="button">Fechar</button><p id="mj-msg" role="status"></p>`;document.body.append(dialog);
// Validação não escreve nem restaura dados no navegador.
const validateLabel=document.createElement('label');validateLabel.textContent='Validar arquivo de backup (somente leitura)';
const backupFile=document.createElement('input');backupFile.type='file';backupFile.accept='.json,application/json';backupFile.id='mj-backup-file';
backupFile.onchange=async()=>{try{const file=backupFile.files?.[0];if(!file)return;const backup=await MartinsBackup.validate(await file.text());$('mj-msg').textContent='Backup íntegro: '+backup.entries.length+' chave(s). Nenhum dado foi restaurado ou alterado.';}catch(e){$('mj-msg').textContent='Backup inválido: '+e.message;}};
validateLabel.append(backupFile);dialog.append(validateLabel);
// Obras personalizadas persistidas voltam aos seletores originais após recarregar.
function ensureWorks(){for(const id of ['obra-select','gestao-obra-select','filtro-obra-hist']){const select=$(id);if(!select)continue;for(const name of Object.keys(dadosObras))if(![...select.options].some(x=>x.value===name))select.add(new Option(name,name));}}
ensureWorks();if(document.addEventListener)document.addEventListener('DOMContentLoaded',ensureWorks);

const auditSection=document.createElement('section');auditSection.innerHTML='<h3>Planejado × Frequência × RDO</h3><p>Fontes comparadas separadamente. Rascunho não comprova execução.</p><div style="overflow:auto"><table><thead><tr><th>Funcionário</th><th>Obra</th><th>Planejado</th><th>Frequência</th><th>RDO aprovado</th><th>Rascunho</th><th>Conferência</th></tr></thead><tbody id="mj-audit"></tbody></table></div><p id="mj-audit-warnings"></p>';dialog.append(auditSection);
function renderAudit(rows,freq){const result=typeof MartinsConferencia!=='undefined'?MartinsConferencia.build({plans:rows,frequency:freq,rdos:getDb(),start:$('mj-day').value,end:$('mj-day').value,employees:employees()}):J.auditDay(rows,freq,getDb(),$('mj-day').value,employees());$('mj-audit').replaceChildren();for(const row of result.lines){const tr=document.createElement('tr');for(const value of [row.nome,row.obra,row.planejado,row.frequencia,row.rdoAprovado,row.rdoRascunho,row.situacao]){const td=document.createElement('td');td.textContent=String(value);tr.append(td);}$('mj-audit').append(tr);}$('mj-audit-warnings').textContent=result.warnings.join('; ');}
let snapshot=null,plansSnapshot=null;
const report=s=>$('mj-msg').textContent=s;const run=fn=>()=>{try{fn();}catch(e){report(e.message);}};
const employees=()=>J.read(localStorage,'cm_colaboradores_db',[]);
function refresh(){const freq=getFrequenciaDiariaDb();for(const option of $('mj-person').options){const e=employees().find(x=>String(x.id)===option.value),status=MartinsPlanejamento.employeeIssue(e,$('mj-day').value)||MartinsPlanejamento.unavailable(option.value,$('mj-day').value,freq,MartinsPlanejamento.config(localStorage));option.disabled=Boolean(status);option.textContent=(e?.nome||option.value)+(option.disabled?' — indisponível: '+status:'');}snapshot=localStorage.getItem(J.KEYS.frequency);const rows=J.read(localStorage,J.KEYS.plans,[]);plansSnapshot=localStorage.getItem(J.KEYS.plans);$('mj-rows').replaceChildren();for(const p of J.preview(rows,freq,$('mj-day').value)){const tr=document.createElement('tr'),td=document.createElement('td'),check=document.createElement('input');check.type='checkbox';check.value=p.id;const blocked=MartinsPlanejamento.unavailable(p.id,$('mj-day').value,freq,MartinsPlanejamento.config(localStorage));check.disabled=p.existing||Boolean(blocked);check.setAttribute('aria-label','Confirmar '+p.items[0].nome);td.append(check);tr.append(td);for(const text of [p.items[0].nome,p.items.map(x=>x.obra+' — '+x.horas+'h').join('; '),p.existing?'Preservar: '+freq[$('mj-day').value][p.id].status:blocked?'Indisponível: '+blocked:p.items.length>1?'Rateio entre obras — conferir horas':'Sem registro']){const cell=document.createElement('td');cell.textContent=text;tr.append(cell);}$('mj-rows').append(tr);}renderAudit(rows,freq);report('Conferência atualizada. Selecione apenas quem efetivamente trabalhou.');}
function open(){const list=employees().filter(x=>x.status!=='Inativo');$('mj-person').replaceChildren();for(const e of list)$('mj-person').add(new Option(e.nome,String(e.id)));$('mj-work').replaceChildren();for(const o of $('obra-select').options)if(o.value)$('mj-work').add(new Option(o.textContent,o.value));$('mj-day').value=$('ponto-data-filtro')?.value||MartinsPersistenciaRdo.brDay();dialog.showModal();refresh();}
const trigger=document.createElement('button');trigger.type='button';trigger.className='mj-open';trigger.id='mj-open';trigger.textContent='Planejar e conferir frequência';trigger.onclick=run(open);$('ponto-data-filtro')?.parentElement.append(trigger);
$('mj-close').onclick=()=>dialog.close();$('mj-close-top').onclick=()=>dialog.close();$('mj-refresh').onclick=run(refresh);$('mj-day').onchange=run(refresh);
$('mj-plan').onclick=run(()=>{const e=employees().find(x=>String(x.id)===$('mj-person').value&&x.status!=='Inativo');if(!e)throw Error('Selecione funcionário ativo');const before=localStorage.getItem(J.KEYS.plans);const next=MartinsPlanejamento.planOne(J.read(localStorage,J.KEYS.plans,[]),{data:$('mj-day').value,funcionarioId:String(e.id),nome:e.nome,obra:$('mj-work').value,horas:Number($('mj-hours').value)},getFrequenciaDiariaDb(),MartinsPlanejamento.config(localStorage),employees());J.write(localStorage,J.KEYS.plans,next,before);refresh();report('Planejamento salvo; frequência ainda não alterada.');});
$('mj-copy').onclick=run(()=>{const days=[...new Set($('mj-dates').value.split(',').map(x=>x.trim()).filter(Boolean))];if(!days.length||days.length>31)throw Error('Informe de 1 a 31 datas');const before=localStorage.getItem(J.KEYS.plans);let rows=J.read(localStorage,J.KEYS.plans,[]);const source=rows.filter(x=>x.data===$('mj-day').value);if(!source.length)throw Error('Dia de origem sem planejamento');const freq=getFrequenciaDiariaDb();for(const day of days){J.date(day);if(rows.some(x=>x.data===day))throw Error('Destino já possui planejamento: '+day);for(const p of source){if(!employees().some(e=>String(e.id)===p.funcionarioId&&e.status!=='Inativo'))throw Error('Funcionário inativo ou removido: '+p.nome);rows=MartinsPlanejamento.planOne(rows,{...p,data:day},freq,MartinsPlanejamento.config(localStorage),employees());}}J.write(localStorage,J.KEYS.plans,rows,before);refresh();report('Planejamento copiado para '+days.length+' dia(s). Confira domingos, feriados e disponibilidade antes de confirmar.');});
$('mj-confirm').onclick=run(()=>{if(localStorage.getItem(J.KEYS.plans)!==plansSnapshot)throw Error('Planejamento mudou. Atualize a conferência.');const ids=[...$('mj-rows').querySelectorAll('input:checked')].map(x=>x.value);if(!ids.length)throw Error('Selecione presenças para confirmar');for(const id of ids)if(!employees().some(x=>String(x.id)===id&&x.status!=='Inativo'))throw Error('Funcionário inativo/removido. Atualize.');for(const id of ids){const reason=MartinsPlanejamento.employeeIssue(employees().find(e=>String(e.id)===id),$('mj-day').value)||MartinsPlanejamento.unavailable(id,$('mj-day').value,getFrequenciaDiariaDb(),MartinsPlanejamento.config(localStorage));if(reason)throw Error('Funcionário indisponível: '+reason);}const next=J.confirm(J.read(localStorage,J.KEYS.plans,[]),getFrequenciaDiariaDb(),$('mj-day').value,ids);J.write(localStorage,J.KEYS.frequency,next,snapshot);renderAuditoriaPonto();refresh();report(ids.length+' presença(s) confirmada(s). RDO permanece independente até inclusão no formulário.');});
const rdoButton=document.createElement('button');rdoButton.type='button';rdoButton.id='mj-rdo';rdoButton.className='mj-open';rdoButton.textContent='Incluir equipe da Frequência';rdoButton.onclick=()=>{try{const edited=window.currentEditingRdoId&&getDb().find(x=>x.id===window.currentEditingRdoId);if(edited&&edited.status!=='Rascunho')throw Error('Reabra o RDO com profissional autorizado antes de alterar.');const incoming=J.rdoWorkers(getFrequenciaDiariaDb(),$('input-data').value,$('obra-select').value,employees());if(!incoming.length)throw Error('Sem presenças nesta obra e data.');const next=J.mergeWorkers(currentTrabalhadores,incoming);currentTrabalhadores=next;renderTrabalhadoresTable();showToast('Equipe conferida incluída no formulário. Salve o RDO após revisar.');}catch(e){showToast(e.message,'warning');}};$('btn-add-trabalhador')?.parentElement.append(rdoButton);
})();
